```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int liczbaDzielnikow(int n) {
    int cnt = 0;
    for (int i = 1; i <= n; i++)
        if (n % i == 0) cnt++;
    return cnt;
}

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);

    int minD = liczbaDzielnikow(tab[0]), maxD = minD;
    int minL = tab[0], maxL = tab[0];
    for (int i = 1; i < (int)tab.size(); i++) {
        int d = liczbaDzielnikow(tab[i]);
        if (d < minD) { minD = d; minL = tab[i]; }
        if (d > maxD) { maxD = d; maxL = tab[i]; }
    }
    cout << "Min dzielnikow: " << minL << " (" << minD << " dzielniki)" << endl;
    cout << "Max dzielnikow: " << maxL << " (" << maxD << " dzielnikow)" << endl;
    return 0;
}
```

